import{_ as t,o as n,c as i,ah as o}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Extended activities","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/extended-modules.md","filePath":"src/en/guide/extended-modules.md"}'),a={name:"en/guide/extended-modules.md"};function r(s,e,d,l,c,h){return n(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="extended-activities" tabindex="-1">Extended activities <a class="header-anchor" href="#extended-activities" aria-label="Permalink to &quot;Extended activities&quot;">​</a></h1><p>Modules 19 to 28, 30, 31 and 33 extend the core without being a prerequisite. They address distinct audiences and actors, but reuse the same accounts, billing and documents.</p><h2 id="b2b-training-on-quotation-module-19" tabindex="-1">B2B training on quotation (module 19) <a class="header-anchor" href="#b2b-training-on-quotation-module-19" aria-label="Permalink to &quot;B2B training on quotation (module 19)&quot;">​</a></h2><p>A company requests training for its employees from the NextBoxx website (API) or from “My company requests”. The request <code>DEM-NB</code> carries the company name, programme, format, headcount and desired date.</p><ol><li>The <strong>Pedagogical Coordinator</strong> sends a quote <code>DEV-NB</code> as a PDF: programme, format, headcount, dates, pace, total amount. Above 15 learners, one cohort per block of 15.</li><li>The contact accepts or refuses the quote in their area; the Coordinator can record the acceptance on their behalf.</li><li>On acceptance, <strong>dedicated cohorts</strong> are opened in the company&#39;s name, without a promotion, and a <strong>single invoice</strong> for the quote amount is issued, due on the first day of training.</li><li>The contact or the Coordinator adds employees within the 15-seat limit. Account created or reused, enrolment active immediately, Learner role, booklet and Sève access. No candidature, no agreement, no individual invoice.</li></ol><p>On non-payment, the dedicated cohorts&#39; enrolments and Sève access are suspended at D+30, then restored on payment. The “settled” condition for a B2B learner is the paid request invoice.</p><h2 id="matching-and-recruitment-modules-23-to-26" tabindex="-1">Matching and recruitment (modules 23 to 26) <a class="header-anchor" href="#matching-and-recruitment-modules-23-to-26" aria-label="Permalink to &quot;Matching and recruitment (modules 23 to 26)&quot;">​</a></h2><p>An organisation submits a <strong>matching</strong> request (internship, apprenticeship, assignment) or a <strong>recruitment</strong> request (permanent or fixed-term contract) from “My company requests”. The form only shows the fields for the chosen type.</p><ul><li>Only a holder of a <strong>NextBoxx certificate</strong> can become visible to companies, with a PDF CV and a short presentation.</li><li>The <strong>Partnerships Officer</strong> proposes visible profiles, in one or several rounds.</li><li>The organisation sees the first name and last-name initial, the certificates and the presentation. A retained profile reveals the name, email, phone and CV, and the learner is notified.</li><li>As soon as a profile is retained, the Officer confirms the matching: an invoice is issued to the contact, due in 30 days, per retained profile, with the matching flat fee and, if requested, the support flat fee.</li><li>Without both flat fees set by the Administrator, confirmation is impossible. Non-payment follows the reminders and moratorium, without suspension.</li></ul><h2 id="events-modules-20-to-22" tabindex="-1">Events (modules 20 to 22) <a class="header-anchor" href="#events-modules-20-to-22" aria-label="Permalink to &quot;Events (modules 20 to 22)&quot;">​</a></h2><p>The <strong>Events Officer</strong> and the Administrator create an event (title, description, dates, venue, seats, price in FCFA, 0 for free), publish it, edit it and cancel it as long as it has not started. Statuses: <strong>draft</strong>, <strong>published</strong>, <strong>cancelled</strong>.</p><ul><li>Registration from the website (API) or from “My events”; <strong>Participant</strong> role added.</li><li>Refused for an organisation account, an already registered account, a closed event, or a suspended account on a paid event.</li><li>Confirmed and pending-payment registrations hold a seat; beyond that, a <strong>waiting list</strong>. A freed seat goes to the first registered person, who is notified.</li><li>Paid event: invoice <code>FAC-NB</code> at registration, due <strong>48 hours before the start</strong>. Full payment confirms. Without payment at 48 hours, the registration is cancelled, the outstanding amount cancelled by credit note, and the seat freed.</li><li>A free event confirms immediately and takes registrations until it starts.</li><li>Cancellation: every registrant is notified; paid amounts are refunded by credit note, outstanding amounts cancelled.</li></ul><p>Event invoices are excluded from the billing calendar, training reminders, commissions and the Direction and Reporting dashboards.</p><h2 id="event-funding-modules-27-and-28" tabindex="-1">Event funding (modules 27 and 28) <a class="header-anchor" href="#event-funding-modules-27-and-28" aria-label="Permalink to &quot;Event funding (modules 27 and 28)&quot;">​</a></h2><p>An <strong>Event Funder</strong> declares a contribution from “My funding”: event, nature (financial, in kind, other), description, amount in FCFA. The Events Officer can also enter a contribution for an account, even after the event ends.</p><ul><li>A contribution stays <strong>declared</strong> until the Officer validates it and records its receipt with the date. It is never counted automatically.</li><li>The Officer can refuse it with a reason. No invoice is issued.</li><li>Validation issues the <strong>funding agreement</strong> <code>CONVE-NB-YYYY-XXX</code>, sent to the funder, without electronic signature.</li><li>The Officer enters the event <strong>expenses</strong> (label, amount, date, optional supporting document) and can correct or delete them.</li><li><strong>Net balance</strong> = received contributions − expenses. The funder sees the total of their contributions, the event expenses and the net balance, without the details of other funders.</li><li>On event cancellation, declared contributions are cancelled; received contributions remain in the balance and their funder is notified.</li></ul><h2 id="l-eclosion-modules-30-and-31" tabindex="-1">L&#39;Éclosion (modules 30 and 31) <a class="header-anchor" href="#l-eclosion-modules-30-and-31" aria-label="Permalink to &quot;L&#39;Éclosion (modules 30 and 31)&quot;">​</a></h2><p>The <strong>Incubation Officer</strong> creates a cycle as a draft (title, submission deadline, start and end), then opens it. Submissions close no later than the start of the incubation.</p><ul><li>Any account applies once per cycle: project name, sector, problem, solution, progress, optional PDF pitch. The <strong>Canopé</strong> path is only offered to an account with Canopé status; others apply as external holders.</li><li>The Officer enters <strong>competition winners</strong> for their account, with the competition name and year.</li><li>The Officer <strong>retains</strong> or <strong>refuses</strong> with a reason. A retained project grants the <strong>Project Holder</strong> role.</li><li>The Officer proposes a <strong>participation</strong>: equity or revenue share, percentage and conditions.</li><li>The <strong>investment committee</strong> votes unanimously: the proposal counts as the Officer&#39;s vote, then the Pedagogical Coordinator and Direction vote, each from a different account. A vote against gives a reason for refusal; a new proposal can then be made.</li></ul><h2 id="technology-partnerships-module-33" tabindex="-1">Technology partnerships (module 33) <a class="header-anchor" href="#technology-partnerships-module-33" aria-label="Permalink to &quot;Technology partnerships (module 33)&quot;">​</a></h2><p>The <strong>Partnerships Officer</strong> or the Administrator creates a partnership under negotiation: organisation, solution, nature (pedagogical integration, certification, tool supply), concerned programmes, signing contact, optional end date.</p><ul><li>The partnership is <strong>free</strong>, in exchange for visibility. It is not a marketing partner, which is paid.</li><li>The contract is signed like the Agreement: 7-day email link, full read, code received at the same address, no account. edPage countersigns according to the Administrator&#39;s setting.</li><li>On countersignature, the contract receives its reference <code>CONVP-NB-YYYY-XXX</code> and its sealed PDF; the partnership becomes <strong>active</strong> and its programmes are frozen.</li><li>Visibility (logo, link, presentation, nature) remains editable and appears on the website and in the “Partners” block of the Sève course of the concerned cohorts, updated every hour.</li><li>The partnership ends the day after its end date. A concerned cohort keeps it until its own end if it has started.</li></ul><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>A single engine (email, Sève, WhatsApp) sends all reminders and alerts. Email always goes out; Sève is added for accounts opened in Sève; WhatsApp is added for payment and admission reminders, if the account has a phone number. A failing channel does not block the others.</p><p>Triggers cover payment, admission, roles, certification, attendance, B2B training, matching, events, event funding, partnerships and generated documents. Details are in <a href="/kura-guide/en/guide/integrations.html#notifications">Integrations</a>.</p>',25)])])}const p=t(a,[["render",r]]);export{m as __pageData,p as default};
